mapper.select:
SELECT r.id, r.business_type, r.business_id, r.remind_time, r.content, r.status, r.owner, r.create_time, CASE WHEN r.business_type = 'CUSTOMER' THEN c.name WHEN r.business_type = 'OPPORTUNITY' THEN o.name WHEN r.business_type = 'CLUE' THEN cl.name END as business_name, u.name as owner_name FROM reminder r LEFT JOIN customer c ON c.id = r.business_id AND r.business_type = 'CUSTOMER' LEFT JOIN opportunity o ON o.id = r.business_id AND r.business_type = 'OPPORTUNITY' LEFT JOIN clue cl ON cl.id = r.business_id AND r.business_type = 'CLUE' LEFT JOIN user u ON u.id = r.owner WHERE r.organization_id = #{orgId}
AND r.business_type = #{request.businessType}
AND r.business_id = #{request.businessId}
AND r.status = #{request.status}
AND r.owner = #{userId} ORDER BY r.remind_time DESC
